(function () { (typeof ngDevMode === "undefined" || ngDevMode) && i0.ɵsetClassMetadata(SustainabilityComponent, [{
        type: Component,
        args: [{ selector: 'app-sustainability', template: "<section class=\"oe-hero\">\n    <div class=\"oe-hero__bg1\"></div>\n    <div class=\"oe-hero__overlay\"></div>\n    <div class=\"oe-hero__dot oe-hero__dot--1\"></div>\n    <div class=\"oe-hero__dot oe-hero__dot--2\"></div>\n    <div class=\"oe-hero__dot oe-hero__dot--3\"></div>\n    <div class=\"container\">\n      <div class=\"oe-hero__content reveal\">\n        <span class=\"oe-eyebrow\">\n          <i class=\"fa-solid fa-leaf\"></i> Our Services\n        </span>\n        <h1 class=\"oe-hero__title\">\n          Sustainability<br /><span class=\"oe-hero__accent\">Consulting</span>\n        </h1>\n        <p class=\"oe-hero__sub\">\n          Helping organisations embed sustainability into the core of their\n          business  reducing environmental impact, meeting compliance obligations,\n          and creating long-term value through responsible, future-ready operations.\n        </p>\n        <div class=\"oe-hero__ctas\">\n          <a routerLink=\"/contact\" class=\"oe-btn oe-btn--primary\">\n            Get a Consultation <i class=\"fa-solid fa-arrow-right\"></i>\n          </a>\n          <a href=\"#services\" class=\"oe-btn oe-btn--ghost\">Explore Services</a>\n        </div>\n      </div>\n      <div class=\"oe-hero__stats reveal reveal-delay-2\">\n        <div class=\"oe-hstat\">\n          <span class=\"oe-hstat__num\">150+</span>\n          <span class=\"oe-hstat__label\">EMS Implementations</span>\n        </div>\n        <div class=\"oe-hstat-div\"></div>\n        <div class=\"oe-hstat\">\n          <span class=\"oe-hstat__num\">40%</span>\n          <span class=\"oe-hstat__label\">Avg. Energy Savings</span>\n        </div>\n        <div class=\"oe-hstat-div\"></div>\n        <div class=\"oe-hstat\">\n          <span class=\"oe-hstat__num\">100+</span>\n          <span class=\"oe-hstat__label\">Years Experience (Cumulative)</span>\n        </div>\n        <div class=\"oe-hstat-div\"></div>\n        <div class=\"oe-hstat\">\n          <span class=\"oe-hstat__num\"> </span>\n          <span class=\"oe-hstat__label\"> &amp; </span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"oe-intro\">\n    <div class=\"container\">\n      <div class=\"oe-intro__grid\">\n        <div class=\"oe-intro__text reveal\">\n          <span class=\"oe-eyebrow-dark\">Our Approach</span>\n          <h2 class=\"oe-section-title\">\n            Sustainability as a\n            <span class=\"oe-accent-text\">Business Advantage</span>\n          </h2>\n          <div class=\"oe-divider\"></div>\n          <p>\n            QLSS Sustainability practice helps organisations move beyond\n            compliance to embrace sustainability as a genuine competitive\n            advantage. We work alongside your teams to reduce environmental\n            impact, improve resource efficiency, and build the management\n            systems that sustain progress over time.\n          </p>\n          <p>\n            Our certified auditors and environmental management specialists\n            bring practical, on-the-ground experience across manufacturing,\n            energy, and service industries  delivering ISO-aligned frameworks\n            that drive real-world results.\n          </p>\n          <ul class=\"oe-intro__list\">\n            <li><i class=\"fa-solid fa-circle-check\"></i>ISO 14001 Environmental Management Systems</li>\n            <li><i class=\"fa-solid fa-circle-check\"></i>ISO 50001 Energy Management Systems</li>\n            <li><i class=\"fa-solid fa-circle-check\"></i>Carbon Footprint Assessment &amp; Reduction</li>\n            <li><i class=\"fa-solid fa-circle-check\"></i>ESG Reporting &amp; Compliance Frameworks</li>\n          </ul>\n        </div>\n        <div class=\"oe-intro__image reveal reveal-delay-2\">\n          <div class=\"oe-intro__img-wrap\">\n            <img src=\"assets/img/Sustainability.png\"\n              alt=\"Sustainability Consulting\" loading=\"lazy\" />\n          </div>\n          <div class=\"oe-cert-badge\">\n            <i class=\"fa-solid fa-leaf\"></i>\n            <div>\n              <strong>Certified</strong>\n              <span>ISO 14001 &amp; 50001</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"oe-services\" id=\"services\">\n    <div class=\"oe-services__bg\"></div>\n    <div class=\"container\">\n      <div class=\"oe-section-header reveal\">\n        <span class=\"oe-eyebrow-light\">What We Deliver</span>\n        <h2 class=\"oe-section-title oe-section-title--light\">\n          Our <span class=\"oe-accent-text--light\">Service Areas</span>\n        </h2>\n        <p class=\"oe-section-sub--light\">\n          Practical sustainability consulting services that reduce environmental\n          impact, ensure compliance, and create lasting value for your organisation.\n        </p>\n      </div>\n      <div class=\"oe-services__grid\">\n        <div class=\"oe-card reveal reveal-delay-1\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-seedling\"></i></div>\n          <div class=\"oe-card__num\">01</div>\n          <h3>ISO 14001 EMS Implementation</h3>\n          <p>\n            Full implementation of ISO 14001 Environmental Management Systems \n            from initial gap analysis and aspect impact assessment through to\n            certification readiness. We ensure your EMS is practical, documented,\n            and genuinely embedded in daily operations.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>Gap Analysis</li>\n            <li>Aspect Impact</li>\n            <li>Procedures &amp; SOPs</li>\n            <li>Certification Support</li>\n          </ul>\n        </div>\n        <div class=\"oe-card reveal reveal-delay-2\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-bolt\"></i></div>\n          <div class=\"oe-card__num\">02</div>\n          <h3>ISO 50001 Energy Management</h3>\n          <p>\n            Implementing robust energy management systems that systematically\n            identify and capture energy savings. Our ISO 50001 implementation\n            delivers measurable reductions in energy consumption, cost, and\n            carbon emissions  with a certified framework to sustain them.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>Energy Baseline</li>\n            <li>EnPI Development</li>\n            <li>Action Plans</li>\n            <li>ISO 50001 Certification</li>\n          </ul>\n        </div>\n        <div class=\"oe-card reveal reveal-delay-3\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-cloud\"></i></div>\n          <div class=\"oe-card__num\">03</div>\n          <h3>Carbon Footprint &amp; Reduction</h3>\n          <p>\n            Measuring, understanding, and reducing your organisation's carbon\n            footprint across Scope 1, 2, and 3 emissions. We deliver credible\n            baseline assessments and structured decarbonisation roadmaps aligned\n            with your business commitments and regulatory requirements.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>GHG Inventory</li>\n            <li>Scope 1, 2, 3</li>\n            <li>Decarbonisation Plan</li>\n            <li>Net Zero Pathway</li>\n          </ul>\n        </div>\n        <div class=\"oe-card reveal reveal-delay-1\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-chart-bar\"></i></div>\n          <div class=\"oe-card__num\">04</div>\n          <h3>ESG Reporting &amp; Compliance</h3>\n          <p>\n            Developing ESG reporting frameworks that meet investor, regulatory,\n            and customer expectations. We help you gather the right data, tell\n            your sustainability story credibly, and comply with evolving\n            disclosure requirements including BRSR and GRI standards.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>BRSR Compliance</li>\n            <li>GRI Standards</li>\n            <li>Stakeholder Reporting</li>\n            <li>ESG Data Systems</li>\n          </ul>\n        </div>\n        <div class=\"oe-card reveal reveal-delay-2\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-recycle\"></i></div>\n          <div class=\"oe-card__num\">05</div>\n          <h3>Waste Reduction &amp; Circular Economy</h3>\n          <p>\n            Designing waste reduction programmes that cut disposal costs,\n            improve resource efficiency, and move your organisation toward\n            circular economy principles. From production waste elimination\n            to packaging redesign, we identify practical, measurable improvements.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>Waste Audit</li>\n            <li>Zero Waste to Landfill</li>\n            <li>Circular Economy</li>\n            <li>Packaging Optimisation</li>\n          </ul>\n        </div>\n        <div class=\"oe-card reveal reveal-delay-3\">\n          <div class=\"oe-card__icon\"><i class=\"fa-solid fa-users-gear\"></i></div>\n          <div class=\"oe-card__num\">06</div>\n          <h3>EHS Training &amp; Awareness</h3>\n          <p>\n            Building environmental, health, and safety capability at every level\n            of your organisation. Our practical training programmes  from\n            awareness sessions to certified EHS auditor training  embed the\n            behaviours and knowledge needed to maintain high EHS standards.\n          </p>\n          <ul class=\"oe-card__tags\">\n            <li>EHS Awareness</li>\n            <li>Aspect Impact Training</li>\n            <li>Internal Auditor</li>\n            <li>ISO 14001 Training</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"oe-standards\">\n    <div class=\"container\">\n      <div class=\"oe-section-header reveal\">\n        <span class=\"oe-eyebrow-dark\">Standards &amp; Frameworks</span>\n        <h2 class=\"oe-section-title\">\n          Certified Across\n          <span class=\"oe-accent-text\">Key Sustainability Standards</span>\n        </h2>\n      </div>\n      <div class=\"oe-standards__grid\">\n        <div class=\"oe-std reveal reveal-delay-1\">\n          <i class=\"fa-solid fa-leaf\"></i>\n          <strong>ISO 14001</strong>\n          <span>Environmental Management</span>\n        </div>\n        <div class=\"oe-std reveal reveal-delay-2\">\n          <i class=\"fa-solid fa-bolt\"></i>\n          <strong>ISO 50001</strong>\n          <span>Energy Management</span>\n        </div>\n        <div class=\"oe-std reveal reveal-delay-3\">\n          <i class=\"fa-solid fa-hard-hat\"></i>\n          <strong>ISO 45001</strong>\n          <span>Occupational Health &amp; Safety</span>\n        </div>\n        <div class=\"oe-std reveal reveal-delay-1\">\n          <i class=\"fa-solid fa-chart-bar\"></i>\n          <strong>GRI Standards</strong>\n          <span>Sustainability Reporting</span>\n        </div>\n        <div class=\"oe-std reveal reveal-delay-2\">\n          <i class=\"fa-solid fa-building-columns\"></i>\n          <strong>BRSR</strong>\n          <span>Business Responsibility &amp; Sustainability</span>\n        </div>\n        <div class=\"oe-std reveal reveal-delay-3\">\n          <i class=\"fa-solid fa-cloud\"></i>\n          <strong>GHG Protocol</strong>\n          <span>Carbon Accounting Standard</span>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"oe-process\">\n    <div class=\"container\">\n      <div class=\"oe-section-header reveal\">\n        <span class=\"oe-eyebrow-dark\">How We Work</span>\n        <h2 class=\"oe-section-title\">\n          Our Engagement <span class=\"oe-accent-text\">Process</span>\n        </h2>\n        <p class=\"oe-section-sub\">\n          A structured approach to sustainability transformation that delivers\n          compliance, performance improvement, and lasting change.\n        </p>\n      </div>\n      <div class=\"oe-process__steps\">\n        <div class=\"oe-step reveal reveal-delay-1\">\n          <div class=\"oe-step__num\">01</div>\n          <div class=\"oe-step__icon\"><i class=\"fa-solid fa-clipboard-list\"></i></div>\n          <h3>Assess</h3>\n          <p>Baseline environmental performance review, gap analysis against\n            target standards, and identification of material sustainability issues.</p>\n        </div>\n        <div class=\"oe-step__arrow\"><i class=\"fa-solid fa-chevron-right\"></i></div>\n        <div class=\"oe-step reveal reveal-delay-2\">\n          <div class=\"oe-step__num\">02</div>\n          <div class=\"oe-step__icon\"><i class=\"fa-solid fa-map\"></i></div>\n          <h3>Plan</h3>\n          <p>Sustainability roadmap with prioritised initiatives, measurable\n            targets, and resource requirements  aligned with your business strategy.</p>\n        </div>\n        <div class=\"oe-step__arrow\"><i class=\"fa-solid fa-chevron-right\"></i></div>\n        <div class=\"oe-step reveal reveal-delay-3\">\n          <div class=\"oe-step__num\">03</div>\n          <div class=\"oe-step__icon\"><i class=\"fa-solid fa-hammer\"></i></div>\n          <h3>Implement</h3>\n          <p>Hands-on implementation of management systems, processes, and\n            training  with full documentation and audit trail for certification.</p>\n        </div>\n        <div class=\"oe-step__arrow\"><i class=\"fa-solid fa-chevron-right\"></i></div>\n        <div class=\"oe-step reveal reveal-delay-1\">\n          <div class=\"oe-step__num\">04</div>\n          <div class=\"oe-step__icon\"><i class=\"fa-solid fa-chart-line\"></i></div>\n          <h3>Improve</h3>\n          <p>Continuous monitoring of environmental KPIs, regular management\n            reviews, and ongoing improvement to ensure your sustainability\n            performance keeps advancing.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"oe-cta reveal\">\n    <div class=\"oe-cta__bg\"></div>\n    <div class=\"container\">\n      <div class=\"oe-cta__inner\">\n        <div class=\"oe-cta__text\">\n          <h2>Ready to Build a More<br /><span>Sustainable Business?</span></h2>\n          <p>\n            Connect with our sustainability consulting team today and start\n            your journey toward a more responsible, resilient organisation.\n          </p>\n        </div>\n        <div class=\"oe-cta__actions\">\n          <a routerLink=\"/contact\" class=\"oe-btn oe-btn--white\">\n            Request a Consultation <i class=\"fa-solid fa-arrow-right\"></i>\n          </a>\n          <a routerLink=\"/expertise\" class=\"oe-btn oe-btn--ghost\">View All Services</a>\n        </div>\n      </div>\n    </div>\n  </section>" }]
    }], function () { return [{ type: i1.SiteInteractionsService }, { type: i2.Title }, { type: i2.Meta }]; }, null); })();
